from django.utils import timezone


def fijos_con_horario(apps, schema_editor):
    """Los turnos sin fin pasan a ser fijos de 24 h (hora de fin = hora de inicio):
    siguen vigentes todo el día, como antes, pero ya cumplen la regla de tener hora de fin."""
    Turno = apps.get_model('core', 'Turno')
    for turno in Turno.objects.filter(fin__isnull=True):
        turno.fijo = True
        turno.hora_fin = timezone.localtime(turno.inicio).time()
        turno.save(update_fields=['fijo', 'hora_fin'])


